USE cfb_load;

MERGE INTO cfb.dbo.passing_plays AS target
USING cfb_load.dbo.passing_plays AS source
ON target.game_id = source.game_id
	AND target.play_id = source.play_id
WHEN MATCHED THEN
	UPDATE SET
		drive_id = source.drive_id,
		season = source.season,
		week = source.week,
		season_type = source.season_type,
		offense_id = source.offense_id,
		offense = source.offense,
		offense_conference = source.offense_conference,
		defense_id = source.defense_id,
		defense = source.defense,
		defense_conference = source.defense_conference,
		period = source.period,
		clock_minutes = source.clock_minutes,
		clock_seconds = source.clock_seconds,
		down = source.down,
		distance = source.distance,
		play_text = source.play_text,
		passer_id = source.passer_id,
		passer = source.passer,
		target_id = source.target_id,
		target = source.target,
		outcome = source.outcome,
		air_yards = source.air_yards,
		pass_depth = source.pass_depth,
		pass_direction = source.pass_direction,
		pass_location = source.pass_location,
		total_yards = source.total_yards,
		yards_after_catch = source.yards_after_catch,
		start_yardline = source.start_yardline,
		start_yards_to_goal = source.start_yards_to_goal,
		target_yards_to_goal = source.target_yards_to_goal,
		is_spike = source.is_spike,
		is_throwaway = source.is_throwaway,
		is_intentional_grounding = source.is_intentional_grounding,
		parse_status = source.parse_status,
		ppa = source.ppa,
		success = source.success,
		location_analysis_eligible = source.location_analysis_eligible
WHEN NOT MATCHED THEN
	INSERT (
		game_id,
		play_id,
		drive_id,
		season,
		week,
		season_type,
		offense_id,
		offense,
		offense_conference,
		defense_id,
		defense,
		defense_conference,
		period,
		clock_minutes,
		clock_seconds,
		down,
		distance,
		play_text,
		passer_id,
		passer,
		target_id,
		target,
		outcome,
		air_yards,
		pass_depth,
		pass_direction,
		pass_location,
		total_yards,
		yards_after_catch,
		start_yardline,
		start_yards_to_goal,
		target_yards_to_goal,
		is_spike,
		is_throwaway,
		is_intentional_grounding,
		parse_status,
		ppa,
		success,
		location_analysis_eligible
	)
	VALUES (
		source.game_id,
		source.play_id,
		source.drive_id,
		source.season,
		source.week,
		source.season_type,
		source.offense_id,
		source.offense,
		source.offense_conference,
		source.defense_id,
		source.defense,
		source.defense_conference,
		source.period,
		source.clock_minutes,
		source.clock_seconds,
		source.down,
		source.distance,
		source.play_text,
		source.passer_id,
		source.passer,
		source.target_id,
		source.target,
		source.outcome,
		source.air_yards,
		source.pass_depth,
		source.pass_direction,
		source.pass_location,
		source.total_yards,
		source.yards_after_catch,
		source.start_yardline,
		source.start_yards_to_goal,
		source.target_yards_to_goal,
		source.is_spike,
		source.is_throwaway,
		source.is_intentional_grounding,
		source.parse_status,
		source.ppa,
		source.success,
		source.location_analysis_eligible
	);

TRUNCATE TABLE cfb_load.dbo.passing_plays;
